mapper.select:
select *
 from (
 	select r.*, m.mname, s.sname, s.sfiles
 	from rating r
 	join member m on r.mno = m.mno
 	join store s on r.sno = s.sno
 	where r.sno = #{sno}
 	order by r.rno desc
 )
 where rownum <= 3

mapper.update:
update rating
 set rtitle = #{rtitle}, rcontent = #{rcontent}, rrate = #{rrate}, rfeature = #{rfeature}
 where rno = #{rno}
